package net.battlespades.results;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.*;
import net.battlespades.match.*;

/** Owner-only source result reservation: connection-object baselines, departed accounts and immutable round evidence. */
public final class RoundResultLedger {
    public record Identity(String legacyId,String nickname){public Identity{if(legacyId==null||!legacyId.matches("[0-9]{1,128}")||nickname==null||nickname.isBlank()||nickname.length()>256)throw new IllegalArgumentException("Result identity must be independently verified");}}
    public record Counters(long kills,long deaths,long captures,long score){public Counters{kills=Math.max(0,kills);deaths=Math.max(0,deaths);captures=Math.max(0,captures);score=Math.max(0,score);}Counters minus(Counters old){return new Counters(Math.max(0,kills-old.kills),Math.max(0,deaths-old.deaths),Math.max(0,captures-old.captures),Math.max(0,score-old.score));}boolean empty(){return kills==0&&deaths==0&&captures==0&&score==0;}}
    public record Participation(double connected,double active,double afk,int humanOpponents,int botOpponents){public Participation{if(!Double.isFinite(connected)||!Double.isFinite(active)||!Double.isFinite(afk)||connected<0||active<0||afk<0||humanOpponents<0||botOpponents<0)throw new IllegalArgumentException("Invalid participation evidence");}Participation minus(Participation p){return new Participation(Math.max(0,connected-p.connected),Math.max(0,active-p.active),Math.max(0,afk-p.afk),humanOpponents,botOpponents);}}
    public record Player(Object token,Identity identity,boolean bot,int team,Counters counters,Map<Integer,ProfileStats.Delta> profile,Participation participation){
        public Player{Objects.requireNonNull(token);Objects.requireNonNull(counters);Objects.requireNonNull(participation);if(profile!=null)profile=Collections.unmodifiableMap(new LinkedHashMap<>(profile));}
        public static Player from(Scoreboard.Player p,Identity identity){var s=p.profileStats;return new Player(p.life,identity,p.life.bot(),p.team(),new Counters(p.kills,p.deaths,p.captures,p.score),s==null?null:s.snapshot(),s==null?ZERO_PART:new Participation(s.connectedSeconds,s.activeSeconds,s.afkSeconds,s.humanOpponents,s.botOpponents));}
    }
    public record Context(String serverId,String mode,String playlistId,Integer mapCrc,String relayLobbyId){public Context{ResultOutbox.server(serverId);Objects.requireNonNull(mode);Objects.requireNonNull(playlistId);relayLobbyId=relayLobbyId==null?"":relayLobbyId.strip();if(mode.length()>64||playlistId.length()>128||relayLobbyId.length()>256)throw new IllegalArgumentException("Result context size");}boolean competitive(){return !Set.of("ugc","tut","tutorial").contains(mode.toLowerCase(Locale.ROOT));}}
    private static final Counters ZERO=new Counters(0,0,0,0);private static final Participation ZERO_PART=new Participation(0,0,0,0,0);
    private static final Map<String,Integer> MODE_TOTAL=Map.ofEntries(Map.entry("tdm",192),Map.entry("vip",193),Map.entry("tc",194),Map.entry("occupation",195),Map.entry("occ",195),Map.entry("oc",195),Map.entry("diamond_mine",196),Map.entry("dia",196),Map.entry("ctf",197),Map.entry("cctf",197),Map.entry("zombie",198),Map.entry("zom",198),Map.entry("demolition",199),Map.entry("dem",199),Map.entry("multihill",200),Map.entry("mh",200));
    private static final class Account {String name;int team;boolean connected,managed;Counters counters=ZERO;Participation participation=ZERO_PART;final Map<Integer,ProfileStats.Delta> profile=new LinkedHashMap<>();Account(String name,int team){this.name=name;this.team=team;}Account copy(){var c=new Account(name,team);c.connected=connected;c.managed=managed;c.counters=counters;c.participation=participation;c.profile.putAll(profile);return c;}}
    private final Thread owner=Thread.currentThread();private final Supplier<Instant> wall;private final Supplier<String> ids;
    private final IdentityHashMap<Object,Counters> counters=new IdentityHashMap<>();private final IdentityHashMap<Object,Map<Integer,ProfileStats.Delta>> profiles=new IdentityHashMap<>();private final IdentityHashMap<Object,Participation> participation=new IdentityHashMap<>();
    private final LinkedHashMap<String,Account> departed=new LinkedHashMap<>();private Context context;private Instant started;private String matchId;private boolean completed;
    public RoundResultLedger(Supplier<Instant> wall,Supplier<String> ids){this.wall=Objects.requireNonNull(wall);this.ids=Objects.requireNonNull(ids);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Result ledger outside owner");}
    public boolean completed(){owned();return completed;}
    public void begin(Context value,Collection<Player> players){owned();context=Objects.requireNonNull(value);started=wall.get();matchId=ids.get();ResultOutbox.identifier(matchId);completed=false;departed.clear();participation.clear();for(var p:players)participation.put(p.token,p.participation);}
    public void resetScoreboard(Collection<Player> players){owned();counters.clear();for(var p:players)counters.put(p.token,p.counters);}
    public void depart(Player p){owned();if(p.identity==null||p.bot){forget(p.token);return;}var delta=p.counters.minus(counters.getOrDefault(p.token,ZERO));var profile=profileDelta(p);var part=p.participation.minus(participation.getOrDefault(p.token,ZERO_PART));if(!delta.empty()||!profile.isEmpty()||part.connected>0){var record=departed.computeIfAbsent(p.identity.legacyId,id->new Account(p.identity.nickname,p.team));merge(record,p,delta,profile,part);}forget(p.token);}
    private void forget(Object token){counters.remove(token);profiles.remove(token);participation.remove(token);}
    private Map<Integer,ProfileStats.Delta> profileDelta(Player p){var delta=new LinkedHashMap<Integer,ProfileStats.Delta>();if(p.profile==null)return delta;var before=profiles.getOrDefault(p.token,Map.of());for(var e:p.profile.entrySet()){var old=before.getOrDefault(e.getKey(),new ProfileStats.Delta(0,0));var now=e.getValue();if(now.count()<0||now.score()<0)throw new IllegalArgumentException("Negative profile counter");long count=Math.max(0,now.count()-old.count()),score=Math.max(0,now.score()-old.score());if(count!=0||score!=0)delta.put(e.getKey(),new ProfileStats.Delta(count,score));}return delta;}
    private static void merge(Account record,Player p,Counters delta,Map<Integer,ProfileStats.Delta> profile,Participation part){var old=record.counters;record.counters=new Counters(Math.addExact(old.kills,delta.kills),Math.addExact(old.deaths,delta.deaths),Math.addExact(old.captures,delta.captures),Math.addExact(old.score,delta.score));var a=record.participation;record.participation=new Participation(a.connected+part.connected,a.active+part.active,a.afk+part.afk,Math.max(a.humanOpponents,part.humanOpponents),Math.max(a.botOpponents,part.botOpponents));record.managed|=p.profile!=null;for(var e:profile.entrySet()){var previous=record.profile.getOrDefault(e.getKey(),new ProfileStats.Delta(0,0));record.profile.put(e.getKey(),new ProfileStats.Delta(Math.addExact(previous.count(),e.getValue().count()),Math.addExact(previous.score(),e.getValue().score())));}}
    /** Call only after the delivery owner reserves a memory slot. No await occurs before counter reservation. */
    public Optional<ResultOutbox.Event> capture(Collection<Player> players,Integer winner,boolean finished,Function<String,List<String>> achievements){
        owned();if(context==null)throw new IllegalStateException("Result round not begun");if(!context.competitive())return Optional.empty();var combined=new LinkedHashMap<String,Account>();departed.forEach((id,a)->combined.put(id,a.copy()));var connected=new ArrayList<Player>();
        for(var p:players){if(p.identity==null||p.bot)continue;connected.add(p);var a=combined.computeIfAbsent(p.identity.legacyId,id->new Account(p.identity.nickname,p.team));merge(a,p,p.counters.minus(counters.getOrDefault(p.token,ZERO)),profileDelta(p),p.participation.minus(participation.getOrDefault(p.token,ZERO_PART)));a.team=p.team;a.connected=true;}
        Instant ended=wall.get();long duration=Math.max(0,Duration.between(started,ended).getSeconds());boolean evidence=duration>=30&&duration<=14400&&context.mapCrc!=null;var results=new ArrayList<Map<String,Object>>();
        for(var e:combined.entrySet()){var a=e.getValue();if(a.counters.empty()&&a.profile.isEmpty()&&a.participation.connected<=0)continue;var stats=new LinkedHashMap<String,Object>();stats.put("1",List.of(a.counters.kills,a.counters.kills));stats.put("220",List.of(a.counters.deaths,0));stats.put("201",List.of(1,a.counters.score));if(a.counters.captures>0&&Set.of("ctf","cctf","classic_ctf").contains(context.mode))stats.put("49",List.of(a.counters.captures,a.counters.captures));if(a.managed){stats.put("1",List.of(0,0));stats.put("220",List.of(0,0));stats.remove("49");}a.profile.forEach((stat,pair)->stats.put(stat.toString(),List.of(pair.count(),pair.score())));var total=MODE_TOTAL.get(context.mode);if(total!=null)stats.put(total.toString(),List.of(1,a.counters.score));boolean complete=finished&&a.connected;if(complete)stats.put(winner==null?"161":winner==a.team?"159":"160",List.of(1,0));
            var result=new LinkedHashMap<String,Object>();result.put("steamid",e.getKey());result.put("name",a.name);result.put("total",List.of(1,a.counters.score));result.put("stats",stats);
            if(evidence){long c=Math.min(duration,seconds(a.participation.connected)),active=Math.min(c,seconds(a.participation.active)),afk=Math.min(c-active,seconds(a.participation.afk));var proof=new LinkedHashMap<String,Object>();proof.put("connected_seconds",c);proof.put("active_seconds",active);proof.put("afk_seconds",afk);proof.put("human_opponents",Math.min(100,a.participation.humanOpponents));proof.put("bot_opponents",Math.min(100,a.participation.botOpponents));proof.put("result",!complete?"unfinished":winner==null?"draw":winner==a.team?"win":"loss");result.put("participation",proof);}
            var unlocked=List.copyOf(achievements.apply("aosplay:"+e.getKey()));if(!unlocked.isEmpty())result.put("achievements",unlocked);results.add(result);
        }
        if(results.isEmpty()){if(finished)completed=true;return Optional.empty();}
        var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id","round_"+ids.get());envelope.put("server_id",context.serverId);envelope.put("recorded_at",timestamp(ended));envelope.put("players",results);if(!context.relayLobbyId.isEmpty())envelope.put("relay_lobby_id",context.relayLobbyId);
        if(evidence){var match=new LinkedHashMap<String,Object>();match.put("match_id",matchId);match.put("playlist_id",context.playlistId);match.put("mode_id",context.mode);match.put("map_crc",String.format(Locale.ROOT,"%08x",context.mapCrc));match.put("duration_seconds",duration);match.put("started_at",timestamp(started));match.put("ended_at",timestamp(ended));envelope.put("match",match);}
        var event=ResultOutbox.Event.from(envelope);departed.clear();for(var p:connected){counters.put(p.token,p.counters);profiles.put(p.token,p.profile==null?Map.of():p.profile);participation.put(p.token,p.participation);}if(finished)completed=true;return Optional.of(event);
    }
    private static long seconds(double value){if(value>=0x1.0p63)throw new ArithmeticException("Participation seconds overflow");return (long)value;}
    private static String timestamp(Instant value){var at=value.atOffset(ZoneOffset.UTC);String base=DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss",Locale.ROOT).format(at);int micros=at.getNano()/1000;return base+(micros==0?"":String.format(Locale.ROOT,".%06d",micros))+"+00:00";}
}
